def get_last_digit_error(series_str):
    decimals = series_str.str.split(".").str[1].str.len().max()
    if pd.isna(decimals) or decimals == 0:
        return 1.0
    return 10.0 ** (-decimals)


# ==========================================
# Part 1: Excitation Energy Analysis & Plotting
# ==========================================
def analyze_and_plot_fh_files(
    file_paths, output_svg="fh_characteristic_curves.svg", verbose=True
):
    plt.figure(figsize=(11, 6))
    results_summary = {}
    tab10_colors = [
        "#1f77b4",
        "#ff7f0e",
        "#2ca02c",
        "#d62728",
        "#9467bd",
        "#8c564b",
        "#e377c2",
        "#7f7f7f",
        "#bcbd22",
        "#17becf",
    ]

    for i, path in enumerate(file_paths):
        path = Path(path)
        try:
            name = path.name
            data_str = EMBEDDED_DATA.get(name)
            if data_str:
                lines = data_str.splitlines()
                df_str = pd.read_csv(
                    io.StringIO(data_str), sep="\t", header=5, dtype=str
                )
            else:
                lines = path.read_text().splitlines()
                df_str = pd.read_csv(path, sep="\t", header=5, dtype=str)

            metadata_text = "\n".join(lines[:5])
            v_ret_match = re.search(r"Vr\(V\)=\s*([\d.]+)", metadata_text)
            v_ret = v_ret_match.group(1) if v_ret_match else "1.5"

            heater_match = re.search(
                r"Cathode Heater Current \(mA\) =\s*([\d.]+)", metadata_text
            )
            heater = heater_match.group(1) if heater_match else "Unknown"
            raw_voltage = df_str.iloc[:, 0].astype(float).to_numpy()
            raw_current = df_str.iloc[:, 1].astype(float).to_numpy()

            v_diffs = np.abs(np.diff(raw_voltage))
            step_size = np.round(np.median(v_diffs[v_diffs > 0]), 3)
            v_error_inst = step_size
            i_error_inst = get_last_digit_error(df_str.iloc[:, 1])

            valid_mask = raw_voltage >= 5.0
            voltage = raw_voltage[valid_mask]
            current = raw_current[valid_mask]

            if len(voltage) == 0:
                continue

            min_sample_distance = int(3.5 / step_size)

            peaks_idx, _ = find_peaks(
                current,
                distance=min_sample_distance,
                prominence=np.ptp(current) * 0.03,
                width=5,
            )

            if len(peaks_idx) < 1:
                plt.errorbar(
                    raw_voltage,
                    raw_current,
                    yerr=i_error_inst,
                    fmt=".",
                    alpha=0.2,
                    label=f"Data ({path.name})",
                    color=tab10_colors[i % len(tab10_colors)],
                    elinewidth=0.5,
                )
                continue

            peak_voltages = voltage[peaks_idx]
            peak_currents = current[peaks_idx]
            peak_total_errors = np.full_like(peak_voltages, v_error_inst)

            has_multiple_peaks = len(peak_voltages) >= 2
            if has_multiple_peaks:
                peak_diffs = np.diff(peak_voltages)
                n_diffs = len(peak_diffs)
                excitation_energy = np.mean(peak_diffs)
                excitation_energy_error = (
                    np.sqrt(peak_total_errors[-1] ** 2 + peak_total_errors[0] ** 2)
                    / n_diffs
                )
                contact_potential = peak_voltages[0] - excitation_energy
                contact_pot_error = np.sqrt(
                    (len(peak_voltages) / n_diffs) ** 2 * peak_total_errors[0] ** 2
                    + (1.0 / n_diffs) ** 2 * peak_total_errors[-1] ** 2
                )
            else:
                excitation_energy = np.nan
                excitation_energy_error = np.nan
                contact_potential = np.nan
                contact_pot_error = np.nan
                peak_diffs = []

            results_summary[path] = {
                "heater_mA": heater,
                "v_ret_V": v_ret,
                "excitation_energy_eV": excitation_energy,
                "excitation_energy_error_eV": excitation_energy_error,
                "contact_potential_V": contact_potential,
                "contact_potential_error_V": contact_pot_error,
                "peaks": list(
                    zip(
                        peak_voltages,
                        peak_currents,
                        peak_total_errors,
                        strict=True,
                    )
                ),
                "peak_diffs": peak_diffs,
                "v_error_inst": v_error_inst,
                "i_error_inst": i_error_inst,
            }

            clean_label = f"$I_h$ = {heater} mA, $V_r$ = {v_ret} V"
            eb = plt.errorbar(
                raw_voltage,
                raw_current,
                yerr=i_error_inst,
                fmt=".",
                label=clean_label,
                markersize=4.0,
                elinewidth=0.8,
                alpha=0.85,
                capsize=2,
                zorder=3,
                color=tab10_colors[i % len(tab10_colors)],
            )

            color = eb[0].get_color()
            plt.scatter(
                peak_voltages,
                peak_currents,
                color=color,
                s=80,
                edgecolors="white",
                linewidths=1.5,
                zorder=5,
            )

            is_260ma = "260ma" in path.name.lower() or heater == "260"
            y_offset = -25 if is_260ma else 12

            for v, cur, _ in results_summary[path]["peaks"]:
                plt.annotate(
                    f"{v:.2f}V",
                    xy=(v, cur),
                    xytext=(0, y_offset),
                    textcoords="offset points",
                    ha="center",
                    fontsize=12,
                    fontweight="bold",
                    bbox=dict(
                        boxstyle="round,pad=0.3",
                        fc="#ffffff",
                        ec=color,
                        alpha=0.9,
                        linewidth=1.2,
                    ),
                    zorder=6,
                )

        except Exception as e:
            print(f"Error processing file {path}: {e}")

    set_style(
        xlabel=r"Acceleration voltage ($V_a$) [V]",
        ylabel="Collector current [pA]",
    )
    plt.xlim(0, 31)
    plt.ylim(bottom=0)
    plt.legend(
        loc="upper left",
        frameon=True,
        facecolor="#ffffff",
        edgecolor="#d1d5db",
        framealpha=0.95,
        fontsize=14,
        shadow=True,
    )
    plt.tight_layout()
    plt.savefig(output_svg, format="svg")
    plt.close()

    return results_summary


# ==========================================
# Part 2: Ionization Energy Analysis & Plotting
# ==========================================
def analyze_ionization_experiment(
    ionization_file_path,
    contact_potential_V,
    contact_pot_error_V=0.0,
    output_svg="fh_ionization_curve.svg",
):
    ionization_file_path = Path(ionization_file_path)
    name = ionization_file_path.name
    data_str = EMBEDDED_DATA.get(name)
    if data_str:
        df_str = pd.read_csv(io.StringIO(data_str), sep="\t", header=5, dtype=str)
    else:
        df_str = pd.read_csv(ionization_file_path, sep="\t", header=5, dtype=str)

    raw_voltage = df_str.iloc[:, 0].astype(float).to_numpy()
    raw_current = df_str.iloc[:, 1].astype(float).to_numpy()

    v_diffs = np.abs(np.diff(raw_voltage))
    step_size = np.round(np.median(v_diffs[v_diffs > 0]), 3)
    v_error_inst = step_size
    i_error_inst = get_last_digit_error(df_str.iloc[:, 1])

    baseline_mask = (raw_voltage >= 2.0) & (raw_voltage <= 8.0)
    baseline_currents = raw_current[baseline_mask]
    if len(baseline_currents) == 0:
        baseline_currents = raw_current[: int(len(raw_current) * 0.3)]

    mean_noise = np.mean(baseline_currents)
    std_noise = np.std(baseline_currents, ddof=1)
    mean_noise_err = std_noise / np.sqrt(len(baseline_currents))

    statistical_noise_ceiling = mean_noise + (5.0 * std_noise)

    v_initial_rise = None
    for i in range(len(raw_voltage) - 3):
        if (
            raw_current[i] > statistical_noise_ceiling
            and raw_current[i + 1] > raw_current[i]
            and raw_current[i + 2] > raw_current[i + 1]
        ):
            v_initial_rise = raw_voltage[i]
            break

    if v_initial_rise is None:
        idx_above = np.where(raw_current > statistical_noise_ceiling)[0]
        if len(idx_above) > 0:
            v_initial_rise = raw_voltage[idx_above[0]]
        else:
            v_initial_rise = raw_voltage[0]

    dI_dV = np.gradient(raw_current, raw_voltage)

    valid_indices = np.where(raw_voltage > 7.0)[0]
    if len(valid_indices) == 0:
        valid_indices = np.arange(len(raw_voltage))

    max_slope_idx = valid_indices[np.argmax(dI_dV[valid_indices])]

    window_size = 2
    fit_start = max(0, max_slope_idx - window_size)
    fit_end = min(len(raw_voltage), max_slope_idx + window_size + 1)

    x_fit = raw_voltage[fit_start:fit_end]
    y_fit = raw_current[fit_start:fit_end]

    slope, intercept = np.polyfit(x_fit, y_fit, 1)

    v_onset = (mean_noise - intercept) / slope
    v_onset_err = v_error_inst

    true_ionization_energy = v_onset - contact_potential_V
    total_error = np.sqrt(v_onset_err**2 + contact_pot_error_V**2)

    fig, ax = plt.subplots(figsize=(10, 6))

    ax.errorbar(
        raw_voltage,
        raw_current,
        xerr=v_error_inst,
        yerr=i_error_inst,
        fmt=".",
        color="#2E86AB",
        label="Ion Current Data (I)",
        markersize=4.0,
        elinewidth=1.0,
        alpha=0.9,
        capsize=2,
        zorder=2,
    )

    ax.axvline(
        x=v_initial_rise,
        color="#4CAF50",
        linestyle=":",
        linewidth=2.5,
        label=f"Initial Current Rise (~{v_initial_rise:.2f} V)",
        zorder=3,
    )
    idx_initial = np.abs(raw_voltage - v_initial_rise).argmin()
    ax.scatter(
        raw_voltage[idx_initial],
        raw_current[idx_initial],
        color="#4CAF50",
        s=120,
        marker="X",
        zorder=5,
    )

    x_extrapolate = np.linspace(
        v_onset,
        raw_voltage[fit_end] if fit_end < len(raw_voltage) else max(raw_voltage),
        100,
    )
    y_extrapolate = slope * x_extrapolate + intercept
    ax.plot(
        x_extrapolate,
        y_extrapolate,
        color="orange",
        linestyle="-",
        linewidth=2,
        label="Linear Regression",
        zorder=3,
    )

    ax.axvline(
        x=v_onset,
        color="#C73E1D",
        linestyle="-.",
        linewidth=2.5,
        label=f"Extrapolated Onset ($V_{{a0}}$ = {v_onset:.2f} V)",
    )
    ax.scatter(
        v_onset,
        mean_noise,
        color="#C73E1D",
        s=150,
        edgecolors="white",
        linewidths=2.5,
        zorder=5,
    )

    ax.scatter(x_fit, y_fit, color="#FCA311", s=80, label="Fit Region", zorder=4)

    set_style(
        ax=ax,
        xlabel=r"Acceleration voltage ($V_a$) [V]",
        ylabel="Collector current [pA]",
    )
    ax.set_xlim(0, 15)
    ax.set_ylim(mean_noise - 5, 1000)

    ax.legend(loc="upper left", frameon=True, shadow=True, fontsize=14)
    plt.tight_layout()
    plt.savefig(output_svg, format="svg")
    plt.close()

    return {
        "fitted_ionization_onset_V": v_onset,
        "fitted_ionization_onset_error_V": v_onset_err,
        "true_ionization_energy_eV": true_ionization_energy,
        "error_eV": total_error,
        "mean_noise": mean_noise,
        "mean_noise_err": mean_noise_err,
        "std_noise": std_noise,
    }


# ==========================================
# Main Orchestrator
# ==========================================
def main():
    console = Console()
    base_dir = Path(__file__).resolve().parent

    fh_files = [
        base_dir / "data/step10_270ma.csv",
        base_dir / "data/step10_250ma.csv",
        base_dir / "data/step10_260ma.csv",
    ]

    console.print(
        Panel.fit(
            "[bold yellow]*** FRANCK-HERTZ EXPERIMENT - COMPLETE ANALYSIS SCRIPT ***[/bold yellow]\n"
            "[dim]Part 1: Excitation Energy & Part 2: Ionization Potential[/dim]",
            border_style="bold gold1",
            padding=(1, 4),
            title="[bold green]Technion Physics Lab 4[/bold green]",
        )
    )

    # ----------------------------------------------------
    # RUN PART 1: EXCITATION ENERGY ANALYSIS
    # ----------------------------------------------------
    console.print(
        "\n[bold cyan]>> Running Part 1: Excitation Energy Analysis...[/bold cyan]"
    )
    results = analyze_and_plot_fh_files(
        fh_files,
        output_svg=base_dir / "fh_characteristic_curves.svg",
        verbose=True,
    )

    peaks_table = Table(
        title="\n[bold cyan]1. Detected Peak Positions[/bold cyan]",
        show_header=True,
        header_style="bold magenta",
    )
    peaks_table.add_column("Run", style="bold dim")
    peaks_table.add_column("Peak", justify="center")
    peaks_table.add_column("Voltage [V]", justify="right", style="green")
    peaks_table.add_column("Error [V]", justify="right", style="yellow")
    peaks_table.add_column("Peak Current [pA]", justify="right", style="magenta")

    for _path, res in results.items():
        heater = res["heater_mA"]
        peaks = res["peaks"]
        for idx, peak in enumerate(peaks):
            v_val, i_val, v_err_tot = peak
            run_name = f"{heater} mA" if idx == 0 else ""
            peaks_table.add_row(
                run_name,
                f"Peak {idx + 1}",
                f"{v_val:.2f}",
                f"{v_err_tot:.2f}",
                f"{i_val:.2f}",
            )
        peaks_table.add_row("", "", "", "", "")

    console.print(peaks_table)

    spacings_table = Table(
        title="[bold cyan]2. Peak Spacings & Weighted Averages[/bold cyan]",
        show_header=True,
        header_style="bold magenta",
    )
    spacings_table.add_column("Run (Heater Current)", style="bold dim")
    spacings_table.add_column("Peak Spacings (dV) [V]", justify="right")
    spacings_table.add_column(
        "Weighted Spacing Average [V]", justify="right", style="bold green"
    )
    spacings_table.add_column(
        "Contact Potential Vc [V]", justify="right", style="bold yellow"
    )

    run_averages = []
    run_errors = []
    run_contact_pots = []
    run_contact_pot_errors = []

    for _path, res in results.items():
        heater = res["heater_mA"]
        peaks = res["peaks"]

        n_peaks = len(peaks)
        if n_peaks < 2:
            continue

        v_first, _, v_err_first = peaks[0]
        v_last, _, v_err_last = peaks[-1]

        spacings = []
        spacing_errors = []
        for i in range(n_peaks - 1):
            v1, _, v1_err_tot = peaks[i]
            v2, _, v2_err_tot = peaks[i + 1]
            spacings.append(v2 - v1)
            spacing_errors.append(np.sqrt(v1_err_tot**2 + v2_err_tot**2))

        n_spacings = n_peaks - 1
        exc_energy = (v_last - v_first) / n_spacings
        exc_energy_err = np.sqrt(v_err_last**2 + v_err_first**2) / n_spacings

        run_averages.append(exc_energy)
        run_errors.append(exc_energy_err)

        contact_pot = v_first - exc_energy

        c_first = n_peaks / n_spacings
        c_last = 1.0 / n_spacings
        contact_pot_err = np.sqrt(
            (c_first * v_err_first) ** 2 + (c_last * v_err_last) ** 2
        )

        run_contact_pots.append(contact_pot)
        run_contact_pot_errors.append(contact_pot_err)

        spacings_str = ", ".join(
            f"{s:.2f} ± {se:.3f}"
            for s, se in zip(spacings, spacing_errors, strict=False)
        )
        spacings_table.add_row(
            f"{heater} mA",
            spacings_str,
            f"{exc_energy:.3f} ± {exc_energy_err:.3f}",
            f"{contact_pot:.3f} ± {contact_pot_err:.3f}",
        )

    console.print(spacings_table)

    weights_global = 1.0 / (np.array(run_errors) ** 2)
    global_weighted_avg = np.sum(np.array(run_averages) * weights_global) / np.sum(
        weights_global
    )
    global_weighted_avg_err = 1.0 / np.sqrt(np.sum(weights_global))

    weights_cp = 1.0 / (np.array(run_contact_pot_errors) ** 2)
    global_cp = np.sum(np.array(run_contact_pots) * weights_cp) / np.sum(weights_cp)
    global_cp_err = 1.0 / np.sqrt(np.sum(weights_cp))

    lit_value = 4.89
    abs_dev = abs(global_weighted_avg - lit_value)
    rel_dev = (abs_dev / lit_value) * 100
    sigma_diff = abs_dev / global_weighted_avg_err

    summary_text = (
        f"[bold gold1]Overall Weighted Average of Averages:[/bold gold1]\n"
        f"  - E_exc = [bold green]{global_weighted_avg:.3f} ± {global_weighted_avg_err:.3f} eV[/bold green]\n"
        f"  - V_c   = [bold yellow]{global_cp:.3f} ± {global_cp_err:.3f} V[/bold yellow]\n\n"
        f"[bold cyan]Comparison with Literature ({lit_value} eV):[/bold cyan]\n"
        f"  - Absolute Deviation: {abs_dev:.3f} eV\n"
        f"  - Relative Deviation: {rel_dev:.2f}%\n"
        f"  - Statistical Significance: {sigma_diff:.2f} sigma"
    )

    console.print(
        Panel.fit(
            summary_text,
            title="[bold white]Part 1 Results Summary[/bold white]",
            border_style="gold1",
        )
    )

    # ----------------------------------------------------
    # RUN PART 2: IONIZATION POTENTIAL ANALYSIS
    # ----------------------------------------------------
    console.print(
        "\n[bold cyan]>> Running Part 2: Ionization Potential Analysis...[/bold cyan]"
    )
    ion_results = analyze_ionization_experiment(
        base_dir / "data/step2_280ma.csv",
        contact_potential_V=global_cp,
        contact_pot_error_V=global_cp_err,
        output_svg=base_dir / "fh_ionization_curve.svg",
    )

    noise_table = Table(
        title="\n[bold cyan]Baseline Noise Analysis[/bold cyan]",
        show_header=True,
        header_style="bold magenta",
    )
    noise_table.add_column("Metric", style="dim")
    noise_table.add_column("Value [pA]", justify="right", style="green")
    noise_table.add_row(
        "Mean baseline noise",
        f"{ion_results['mean_noise']:.3f} ± {ion_results['mean_noise_err']:.3f}",
    )
    noise_table.add_row("Std. dev. baseline noise", f"{ion_results['std_noise']:.3f}")
    console.print(noise_table)

    e_ion = ion_results["true_ionization_energy_eV"]
    e_ion_err = ion_results["error_eV"]
    lit_val = 10.438
    abs_dev_ion = abs(e_ion - lit_val)
    rel_dev_ion = (abs_dev_ion / lit_val) * 100
    sigma_diff_ion = abs_dev_ion / e_ion_err

    summary_text_ion = (
        f"[bold gold1]Experimental Ionization Metrics (Extrapolation Method):[/bold gold1]\n"
        f"  - Extrapolated Onset Vi = {ion_results['fitted_ionization_onset_V']:.3f} ± {ion_results['fitted_ionization_onset_error_V']:.3f} V\n"
        f"  - Contact potential shift Vc = {global_cp:.3f} ± {global_cp_err:.3f} V\n"
        f"  - True Ionization Energy E_ion = [bold green]{e_ion:.3f} ± {e_ion_err:.3f} eV[/bold green]\n\n"
        f"[bold cyan]Comparison with Literature ({lit_val} eV):[/bold cyan]\n"
        f"  - Absolute Deviation: {abs_dev_ion:.3f} eV\n"
        f"  - Relative Deviation: {rel_dev_ion:.2f}%\n"
        f"  - Statistical Significance: {sigma_diff_ion:.2f} sigma"
    )
    console.print(
        Panel.fit(
            summary_text_ion,
            title="[bold white]Part 2 Results Summary[/bold white]",
            border_style="gold1",
        )
    )


if __name__ == "__main__":
    main()
